/**
 *  Review-throughput instrumentation (M2.1). `median_seconds` is the median gap between consecutive
 *  human decisions, counting only within-session gaps (deltas above `SESSION_GAP_MS` are treated as
 *  breaks, not review time). This is the honest s/segment figure the C3 ≥3× gate measures against.
 */
export type ReviewTimingStats = {
	// Total rows in decision_log (one per recorded human decision that carried a timestamp).
	decisionsLogged: number,
	// Median within-session seconds per decision, or None when there are fewer than 2 timed decisions.
	medianSeconds: number | null,
	// Number of consecutive-decision deltas that fell within a session and fed the median.
	samples: number,
};

/**
 *  One compare-and-set metadata edit. `expected` is the exact last server value observed by the
 *  renderer; `value` is the requested replacement. Keeping the two fields explicit makes clearing a
 *  nullable value distinguishable from omitting that field entirely.
 */
export type SegmentMetadataChangeV1 = { field: "speakerId"; expected: string | null; value: string | null } | { field: "alignmentJson"; expected: string | null; value: string | null };

export type SegmentsPage = {
	items: SpeechSegment[],
	total: number,
	nextCursor: string | null,
	/**
	 *  Database-owned revision paired with each list row by the same SQLite result row. Typed review
	 *  IPC consumes this map; legacy list callers safely ignore the additive field.
	 */
	revisions?: { [key in string]: number },
	/**
	 *  True when a voice focus narrowed this page — i.e. `total` counts a SUBSET of the library.
	 *
	 *  The page needs this to tell the truth. Review mode measures progress against the corpus and
	 *  fires an "all clips reviewed" banner when its queue empties, a rule it already suppresses for
	 *  a SEARCH subset. A focus is a subset too, so without this flag draining 1,318 focused clips
	 *  announced a 15,262-clip library as finished (review 2026-08-20).
	 */
	focusNarrowed?: boolean,
};

